        card=Ui.card(context);Ui.pad(card,12,6,12,12);card.setElevation(dp(12));card.setOnClickListener(v->{});cardAt=new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER);root.addView(card,cardAt);
        LinearLayout head=Ui.row(context);title=Ui.text(context,"浏览器",16,Ui.INK,true);title.setSingleLine();title.setEllipsize(TextUtils.TruncateAt.END);title.setContentDescription("拖动浏览器窗口");Ui.pad(title,4,0,4,0);head.addView(title,new LinearLayout.LayoutParams(0,dp(44),1));title.setGravity(Gravity.CENTER_VERTICAL);dragTitle();
        foldButton=Ui.tool(context,"collapse","收起浏览器",()->fold(!folded));pinButton=Ui.tool(context,"pin","置顶浏览器",()->{pinned=!pinned;layout();});head.addView(foldButton,new LinearLayout.LayoutParams(dp(40),dp(40)));head.addView(pinButton,new LinearLayout.LayoutParams(dp(40),dp(40)));head.addView(Ui.tool(context,"close","关闭浏览器",dismiss),new LinearLayout.LayoutParams(dp(40),dp(40)));card.addView(head);
        body=Ui.column(context);card.addView(body,new LinearLayout.LayoutParams(-1,0,1));LinearLayout controls=Ui.row(context);
